mapper.sql:
WHERE p.account_id=#{accountId} AND p.status IN ('COMPLETED','CANCELLED')

AND p.status=#{query.status}

AND p.tutorial_id=#{query.tutorialId}

AND LOCATE(#{query.keyword},p.name) > 0

WHERE s.account_id=#{accountId}

AND s.status=#{query.status}

AND s.session_type=#{query.sessionType}


  AND (s.tutorial_id=#{query.tutorialId} OR EXISTS (SELECT 1 FROM sr_learning_session_item i WHERE i.session_id=s.id AND i.account_id=#{accountId} AND i.tutorial_id=#{query.tutorialId}))


AND s.started_at >= #{query.fromTime}

AND s.started_at < #{query.untilTime}


  AND (LOCATE(#{query.keyword},COALESCE(t.title,'')) > 0 OR LOCATE(#{query.keyword},COALESCE(c.title,'')) > 0
    OR LOCATE(#{query.keyword},COALESCE(p.name,'')) > 0
    OR EXISTS (SELECT 1 FROM sr_learning_session_item i WHERE i.session_id=s.id AND i.account_id=#{accountId} AND LOCATE(#{query.keyword},i.front_text) > 0))

mapper.select:
SELECT s.id,s.account_id,s.session_type,s.study_round,s.study_plan_id,s.study_task_id,s.tutorial_id,s.chapter_id,s.status,
  s.study_round,s.requested_item_count,s.summary_json,s.started_at,s.completed_at,s.abandoned_at,t.title tutorial_title,c.title chapter_title,p.name plan_name

ORDER BY s.started_at DESC,s.id DESC LIMIT #{query.pageSize} OFFSET #{query.offset}
